"},{"path":"src/app.py","content":"from enum import Enum
from fractions import Fraction
from uuid import UUID, uuid4
from fastapi import FastAPI, HTTPException
from pydantic import BaseModel, ConfigDict, Field, StrictInt

app = FastAPI()


class DecisionEnum(str, Enum):
    approve = "approve"
    refer = "refer"
    decline = "decline"


class StatusEnum(str, Enum):
    decided = "decided"


class ApplicationCreate(BaseModel):
    model_config = ConfigDict(extra="forbid")

    applicant_ref: str = Field(pattern=r"^A\d{7}$")
    annual_income: StrictInt = Field(ge=1, le=10_000_000)
    requested_amount: StrictInt = Field(ge=500, le=1_000_000)
    term_months: StrictInt = Field(ge=6, le=84)
    monthly_debt: StrictInt = Field(ge=0, le=1_000_000)


class ApplicationCreateResponse(BaseModel):
    id: UUID
    status: StatusEnum
    decision: DecisionEnum


class ApplicationRecord(ApplicationCreate, ApplicationCreateResponse):
    pass


_applications: dict[UUID, ApplicationRecord] = {}


def _evaluate_decision(payload: ApplicationCreate) -> DecisionEnum:
    monthly_payment = Fraction(payload.requested_amount, payload.term_months)
    monthly_income = Fraction(payload.annual_income, 12)
    dti = (payload.monthly_debt + monthly_payment) / monthly_income

    if dti <= Fraction(36, 100):
        return DecisionEnum.approve
    if dti <= Fraction(45, 100):
        return DecisionEnum.refer
    return DecisionEnum.decline


@app.post("/applications", response_model=ApplicationCreateResponse, status_code=201)
def create_application(payload: ApplicationCreate) -> ApplicationCreateResponse:
    app_id = uuid4()
    decision = _evaluate_decision(payload)
    record = ApplicationRecord(
        id=app_id,
        status=StatusEnum.decided,
        decision=decision,
        **payload.model_dump(),
    )
    _applications[app_id] = record
    return ApplicationCreateResponse(
        id=record.id,
        status=record.status,
        decision=record.decision,
    )


@app.get("/applications/{id}", response_model=ApplicationRecord)
def get_application(id: UUID) -> ApplicationRecord:
    record = _applications.get(id)
    if record is None:
        raise HTTPException(status_code=404, detail="Application not found")
    return record


@app.get("/applications", response_model=list[ApplicationRecord])
def list_applications() -> list[ApplicationRecord]:
    return list(reversed(_applications.values()))
